import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { v2 as cloudinary } from 'cloudinary';
import { Readable } from 'stream';

@Injectable()
export class UploadService {
  private readonly logger = new Logger(UploadService.name);

  constructor(private configService: ConfigService) {
    cloudinary.config({
      cloud_name: this.configService.get('CLOUDINARY_CLOUD_NAME'),
      api_key: this.configService.get('CLOUDINARY_API_KEY'),
      api_secret: this.configService.get('CLOUDINARY_API_SECRET'),
    });
  }

  async uploadImage(file: Express.Multer.File): Promise<{ url: string; publicId: string }> {
    try {
      return new Promise((resolve, reject) => {
        const uploadStream = cloudinary.uploader.upload_stream(
          {
            resource_type: 'image',
            folder: 'sawamart/products',
          },
          (error, result) => {
            if (error) {
              this.logger.error(`Erreur d'upload Cloudinary: ${error.message}`);
              reject(error);
            } else {
              resolve({ url: result.secure_url, publicId: result.public_id });
            }
          },
        );

        const bufferStream = new Readable();
        bufferStream.push(file.buffer);
        bufferStream.push(null);
        bufferStream.pipe(uploadStream);
      });
    } catch (error) {
      this.logger.error(`Échec du téléchargement: ${error.message}`);
      throw new Error(`Impossible de télécharger l'image: ${error.message}`);
    }
  }

  async deleteImage(publicId: string): Promise<void> {
    try {
      await cloudinary.uploader.destroy(publicId);
      this.logger.log(`Image supprimée: ${publicId}`);
    } catch (error) {
      this.logger.error(`Erreur lors de la suppression: ${error.message}`);
      throw new Error(`Impossible de supprimer l'image: ${error.message}`);
    }
  }
}
