// DTOs
export class CreateProductDto {
  @IsString()
  @IsNotEmpty()
  @Length(3, 100)
  name: string;

  @IsString()
  @IsOptional()
  description?: string;

  @IsNumber()
  @Min(0)
  price: number;

  @IsInt()
  @Min(0)
  stock: number;

  @IsUUID()
  categoryId: string;
}

// Contrôleur
@Controller('products')
export class ProductController {
  constructor(private productService: ProductService) {}

  @Post()
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('SELLER')
  @UseInterceptors(
    FilesInterceptor('images', 5, {
      fileFilter: (req, file, callback) => {
        if (!file.originalname.match(/\.(jpg|jpeg|png|gif|webp)$/)) {
          return callback(new BadRequestException('Format d\'image non supporté'), false);
        }
        callback(null, true);
      },
      limits: { fileSize: 5 * 1024 * 1024 },
    }),
  )
  async createProduct(
    @Req() req: Request,
    @Body() createProductDto: CreateProductDto,
    @UploadedFiles() files: Array<Express.Multer.File>,
  ) {
    const sellerId = req.user.id;
    return this.productService.createProduct(sellerId, createProductDto, files);
  }
}

// Service
@Injectable()
export class ProductService {
  constructor(
    @InjectRepository(Product) private productRepository: Repository<Product>,
    @InjectRepository(ProductImage) private productImageRepository: Repository<ProductImage>,
    private uploadService: UploadService,
    private dataSource: DataSource,
  ) {}

  async createProduct(sellerId: string, createProductDto: CreateProductDto, files: Express.Multer.File[]) {
    const queryRunner = this.dataSource.createQueryRunner();
    await queryRunner.connect();
    await queryRunner.startTransaction();

    try {
      // Création du produit
      const product = this.productRepository.create({
        ...createProductDto,
        sellerId,
      });
      const savedProduct = await queryRunner.manager.save(product);

      // Upload des images
      const productImages = [];
      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        const { url, publicId } = await this.uploadService.uploadImage(file);
        const productImage = this.productImageRepository.create({
          url,
          publicId,
          isMain: i === 0, // La première image est la principale
          productId: savedProduct.id,
        });
        productImages.push(productImage);
      }
      await queryRunner.manager.save(productImages);

      // Commit de la transaction
      await queryRunner.commitTransaction();

      // Retourner le produit avec ses images
      return this.productRepository.findOne({
        where: { id: savedProduct.id },
        relations: ['images', 'category', 'seller'],
      });
    } catch (error) {
      await queryRunner.rollbackTransaction();
      throw new InternalServerErrorException('Erreur lors de la création du produit');
    } finally {
      await queryRunner.release();
    }
  }
}
```

<strong>Explications :</strong><ul><li><code>FilesInterceptor</code> avec limite de 5 fichiers et filtrage des formats d'image.</li><li>Transaction TypeORM pour garantir l'atomicité (le produit et les images sont enregistrés ensemble).</li><li>La première image est définie comme <code>isMain: true</code>.</li><li>Les rôles sont vérifiés avec <code>RolesGuard</code> pour restreindre l'accès aux vendeurs.</li><li>Gestion des erreurs avec rollback en cas d'échec (upload Cloudinary ou sauvegarde en base).</li></ul>

