// Dans le service
async updateProduct(id: string, sellerId: string, updateProductDto: UpdateProductDto) {
  const product = await this.productRepository.findOne({
    where: { id, sellerId },
    relations: ['images'],
  });

  if (!product) {
    throw new NotFoundException('Produit non trouvé ou vous n\'êtes pas autorisé');
  }

  Object.assign(product, updateProductDto);
  return this.productRepository.save(product);
}

async deleteProduct(id: string, sellerId: string) {
  const product = await this.productRepository.findOne({
    where: { id, sellerId },
    relations: ['images'],
  });

  if (!product) {
    throw new NotFoundException('Produit non trouvé ou vous n\'êtes pas autorisé');
  }

  const queryRunner = this.dataSource.createQueryRunner();
  await queryRunner.connect();
  await queryRunner.startTransaction();

  try {
    // Suppression des images de Cloudinary
    for (const image of product.images) {
      await this.uploadService.deleteImage(image.publicId);
    }

    // Suppression du produit (les images sont supprimées en cascade)
    await queryRunner.manager.remove(product);
    await queryRunner.commitTransaction();

    return { message: 'Produit supprimé avec succès' };
  } catch (error) {
    await queryRunner.rollbackTransaction();
    throw new InternalServerErrorException('Erreur lors de la suppression du produit');
  } finally {
    await queryRunner.release();
  }
}
