// DTO de filtres
export class ProductFiltersDto {
  @IsOptional()
  @IsUUID()
  categoryId?: string;

  @IsOptional()
  @IsNumber()
  @Min(0)
  minPrice?: number;

  @IsOptional()
  @IsNumber()
  @Min(0)
  maxPrice?: number;

  @IsOptional()
  @IsUUID()
  sellerId?: string;

  @IsOptional()
  @IsInt()
  @Min(1)
  @Default(1)
  page?: number;

  @IsOptional()
  @IsInt()
  @Min(1)
  @Max(100)
  @Default(20)
  limit?: number;

  @IsOptional()
  @IsIn(['price', 'createdAt'])
  sortBy?: 'price' | 'createdAt';

  @IsOptional()
  @IsIn(['ASC', 'DESC'])
  sortOrder?: 'ASC' | 'DESC';
}

// Dans le contrôleur
@Get()
async findAll(@Query() filters: ProductFiltersDto) {
  return this.productService.findAll(filters);
}

@Get(':id')
async findOne(@Param('id') id: string) {
  return this.productService.findOne(id);
}

// Dans le service
async findAll(filters: ProductFiltersDto) {
  const { page = 1, limit = 20, sortBy = 'createdAt', sortOrder = 'DESC' } = filters;

  const queryBuilder = this.productRepository.createQueryBuilder('product')
    .leftJoinAndSelect('product.images', 'images')
    .leftJoinAndSelect('product.category', 'category')
    .leftJoinAndSelect('product.seller', 'seller')
    .where('product.isActive = :isActive', { isActive: true });

  if (filters.categoryId) {
    queryBuilder.andWhere('product.categoryId = :categoryId', { categoryId: filters.categoryId });
  }

  if (filters.minPrice) {
    queryBuilder.andWhere('product.price >= :minPrice', { minPrice: filters.minPrice });
  }

  if (filters.maxPrice) {
    queryBuilder.andWhere('product.price <= :maxPrice', { maxPrice: filters.maxPrice });
  }

  if (filters.sellerId) {
    queryBuilder.andWhere('product.sellerId = :sellerId', { sellerId: filters.sellerId });
  }

  queryBuilder
    .orderBy(`product.${sortBy}`, sortOrder)
    .skip((page - 1) * limit)
    .take(limit);

  const [products, total] = await queryBuilder.getManyAndCount();

  return {
    data: products,
    meta: {
      total,
      page,
      limit,
      totalPages: Math.ceil(total / limit),
    },
  };
}

async findOne(id: string) {
  const product = await this.productRepository.findOne({
    where: { id, isActive: true },
    relations: ['images', 'category', 'seller'],
  });

  if (!product) {
    throw new NotFoundException('Produit non trouvé');
  }

  return product;
}
```

<strong>Optimisations :</strong><ul><li>Utilisation de <code>createQueryBuilder</code> pour des requêtes dynamiques et flexibles.</li><li>Pagination avec <code>skip</code> et <code>take</code> pour limiter les résultats.</li><li>Tri par prix ou par date de création.</li><li>Filtrage par catégorie, prix, vendeur.</li></ul>
